const DATA=window.MODPICKER_DATA;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const state={vehicleId:"z3-2000-28",goal:"balanced",category:"All",query:"",sort:"recommended",hideUnverified:false,difficulty:"All",maxPrice:"Any",rankingCategory:"All",build:[],compare:[],watches:[],buildMeta:{},route:"home",budget:5000,laborRate:0,buildName:"My build"};
const goalWeights={balanced:{overall:.32,reliability:.2,quality:.14,power:.12,handling:.1,value:.12},reliability:{overall:.12,reliability:.36,quality:.2,power:.03,handling:.02,value:.17,confidence:.1},power:{overall:.12,reliability:.11,quality:.09,power:.42,handling:.02,value:.14,confidence:.1},handling:{overall:.13,reliability:.08,quality:.11,power:.02,handling:.44,value:.14,confidence:.08},track:{overall:.14,reliability:.18,quality:.14,power:.2,handling:.22,value:.06,confidence:.06},budget:{overall:.13,reliability:.16,quality:.08,power:.08,handling:.08,value:.42,confidence:.05}};
const goalNames={balanced:"Balanced street",reliability:"Reliability",power:"Power",handling:"Handling",track:"Track",budget:"Budget"};
const difficultyOrder={Easy:1,Moderate:2,Advanced:3,Professional:4};
function boot(){loadState();parseShare();bind();renderAll();route(state.route||"home",false)}
function loadState(){try{const raw=localStorage.getItem("modpicker-state-v2")||localStorage.getItem("modpicker-state");if(raw)Object.assign(state,JSON.parse(raw))}catch(e){console.warn("State load failed",e)}state.buildMeta=state.buildMeta||{};state.watches=state.watches||[];state.compare=state.compare||[];state.build=Array.isArray(state.build)?state.build:[];state.garage=state.garage||{};if(!DATA.vehicles.some(v=>v.id===state.vehicleId))state.vehicleId=DATA.vehicles[0].id}
function saveState(){persistGarage();try{localStorage.setItem("modpicker-state-v2",JSON.stringify({garage:state.garage,vehicleId:state.vehicleId,goal:state.goal,build:state.build,compare:state.compare,watches:state.watches,buildMeta:state.buildMeta,budget:state.budget,laborRate:state.laborRate,buildName:state.buildName,route:state.route}))}catch(e){toast("Browser storage unavailable. Export your build to keep it.")}}
function parseShare(){const token=new URLSearchParams(location.search).get("build");if(!token)return;try{const payload=JSON.parse(atob(token));if(payload.vehicleId&&DATA.vehicles.some(v=>v.id===payload.vehicleId))state.vehicleId=payload.vehicleId;if(payload.goal&&goalNames[payload.goal])state.goal=payload.goal;if(Array.isArray(payload.build))state.build=payload.build.filter(id=>part(id)?.vehicles.includes(state.vehicleId));toast("Shared build loaded") }catch(e){console.warn("Invalid shared build",e)}}
function vehicle(){return DATA.vehicles.find(v=>v.id===state.vehicleId)||DATA.vehicles[0]}
function part(id){return DATA.parts.find(p=>p.id===id)}
function compatibleParts(){return DATA.parts.filter(p=>p.vehicles.includes(state.vehicleId))}
function installInfo(p){return p.install||{difficulty:"Unknown",hours:null}}

function partRecommendations(p){return p.recommended||[]}
function sortedOffers(p){return [...(p.offers||[])].filter(o=>Number.isFinite(o.price)&&o.price>0&&o.in_stock!==false&&Date.now()-Date.parse(o.retrieved_at)>=0&&Date.now()-Date.parse(o.retrieved_at)<7*86400000).sort((a,b)=>a.price-b.price)}

function lowestOffer(p){return sortedOffers(p)[0]||{seller:"Price unavailable",price:null,shipping:"Unknown",status:"Unknown",url:p.officialUrl||"#"}}

function lowestPrice(p){return lowestOffer(p).price}

function medianPrice(p){const a=sortedOffers(p).map(x=>x.price);if(!a.length)return null;const m=Math.floor(a.length/2);return a.length%2?a[m]:(a[m-1]+a[m])/2}
function spread(p){const a=sortedOffers(p).map(x=>x.price);return a.length>1?Math.max(...a)-Math.min(...a):0}
function dealPct(p){const med=medianPrice(p),low=lowestPrice(p);return med?Math.max(0,(med-low)/med*100):0}
function money(n){return n==null||!Number.isFinite(Number(n))?"—":new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",maximumFractionDigits:n%1?2:0}).format(Number(n))}

function goalScore(p){return p.rating.overall}

function toast(msg){const t=$("#toast");if(!t)return;t.textContent=msg;t.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove("show"),1700)}
function bind(){
 $("#vehicleSelect").addEventListener("change",e=>{switchVehicle(e.target.value)});
 $("#goalSelect").addEventListener("change",e=>{state.goal=e.target.value;saveState();renderAll()});
 $("#searchInput").addEventListener("input",e=>{state.query=e.target.value;renderCatalog()});
 $("#categoryFilter").addEventListener("change",e=>{state.category=e.target.value;renderCatalog()});
 $("#difficultyFilter").addEventListener("change",e=>{state.difficulty=e.target.value;renderCatalog()});
 $("#maxPriceFilter").addEventListener("change",e=>{state.maxPrice=e.target.value;renderCatalog()});
 $("#sortSelect").addEventListener("change",e=>{state.sort=e.target.value;renderCatalog()});
 $("#hideUnverified").addEventListener("change",e=>{state.hideUnverified=e.target.checked;renderCatalog()});
 $("#rankingCategoryFilter").addEventListener("change",e=>{state.rankingCategory=e.target.value;renderRankings()});
 $("#budgetInput").addEventListener("input",e=>{state.budget=Math.max(0,Number(e.target.value)||0);saveState();renderBuildSummary()});
 $("#laborRateInput").addEventListener("input",e=>{state.laborRate=Math.max(0,Number(e.target.value)||0);saveState();renderBuildSummary()});
 $("#buildNameInput").addEventListener("input",e=>{state.buildName=e.target.value||"My build";saveState();renderBuildHeader()});
 $$('[data-route]').forEach(el=>el.addEventListener('click',ev=>{ev.preventDefault();route(el.dataset.route)}));
 $("#mobileMenuButton").addEventListener("click",()=>$(".main-nav").classList.toggle("open"));
 $("#dialogClose").addEventListener("click",()=>$("#partDialog").close());
 $("#clearBuildButton").addEventListener("click",()=>{rememberUndo();state.build=[];state.buildMeta={};saveState();renderAll();toast("Build cleared. Use Undo to restore it.")});
 $("#copyBuildButton").addEventListener("click",copyBuild);$("#shareBuildButton").addEventListener("click",shareBuild);
 $("#clearCompareButton").addEventListener("click",()=>{state.compare=[];saveState();renderAll();toast("Comparison cleared")});
}
function route(name,scroll=true){
 if(!['home','catalog','garage','prices','rankings','compare','build'].includes(name))name='home';
 document.body.dataset.view=name;
 document.querySelector('.research-nav')?.removeAttribute('open');
 document.querySelector('#mobileMenuButton')?.setAttribute('aria-expanded','false');
 state.route=name;saveState();
 $$('.view').forEach(v=>v.classList.remove('active-view'));
 const target=$(`#${name}View`);
 if(target)target.classList.add('active-view');
 $$('.nav-link').forEach(n=>{
  n.classList.toggle('active',n.dataset.route===name);
  if(n.dataset.route===name)n.setAttribute('aria-current','page');
  else n.removeAttribute('aria-current');
 });
 $('.main-nav').classList.remove('open');
 if(name==='prices')renderPrices();
 if(name==='rankings')renderRankings();
 if(name==='compare')renderCompare();
 if(name==='build')renderBuild();
 if(scroll){
  target?.setAttribute('tabindex','-1');
  target?.focus({preventScroll:true});
  window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
 }
}
function renderAll(){renderVehicle();renderCatalog();renderCounts();renderPrices();renderRankings();renderCompare();renderBuild()}
function renderVehicle(){const v=vehicle();const count=id=>DATA.parts.filter(p=>p.vehicles.includes(id)).length;const ordered=[...DATA.vehicles].sort((a,b)=>Number(count(b.id)>0)-Number(count(a.id)>0)||a.make.localeCompare(b.make)||a.year-b.year);$("#vehicleSelect").innerHTML=ordered.map(x=>`<option value="${x.id}" ${x.id===v.id?'selected':''}>${x.year} ${x.make} ${x.model} ${x.trim} · ${count(x.id)} parts</option>`).join('');$("#goalSelect").value=state.goal;$("#vehicleName").textContent=`${v.year} ${v.make} ${v.model} ${v.trim}`;$("#vehicleBadges").innerHTML=(v.tags||[]).map(t=>`<span class="badge">${t}</span>`).join('');$("#fitmentSummary").textContent=`${v.chassis} · ${v.engine}`;const cp=compatibleParts();$("#heroCompatible").textContent=cp.length;$("#heroCategories").textContent=new Set(cp.map(p=>p.category)).size;$("#heroOffers").textContent=cp.reduce((s,p)=>s+sortedOffers(p).length,0);$("#heroWatched").textContent=state.watches.length}
function categories(){return["All",...new Set(compatibleParts().map(p=>p.category))].sort((a,b)=>a==='All'?-1:b==='All'?1:a.localeCompare(b))}
function filtered(){let list=compatibleParts();if(state.category!=="All")list=list.filter(p=>p.category===state.category);const q=state.query.trim().toLowerCase();if(q)list=list.filter(p=>[p.brand,p.name,p.category,...(p.tags||[])].join(' ').toLowerCase().includes(q));if(state.hideUnverified)list=list.filter(p=>fitmentVerified(p));if(state.difficulty!=="All")list=list.filter(p=>installInfo(p).difficulty===state.difficulty);if(state.maxPrice!=="Any")list=list.filter(p=>lowestPrice(p)!=null&&lowestPrice(p)<=Number(state.maxPrice));const sorters={recommended:(a,b)=>(goalScore(b)??-1)-(goalScore(a)??-1)||Number(fitmentVerified(b))-Number(fitmentVerified(a))||Number(lowestPrice(b)!=null)-Number(lowestPrice(a)!=null)||(b.liveSources?.length||0)-(a.liveSources?.length||0),rating:(a,b)=>(b.rating.overall??-1)-(a.rating.overall??-1),"price-low":(a,b)=>(lowestPrice(a)??Infinity)-(lowestPrice(b)??Infinity),"price-high":(a,b)=>(lowestPrice(b)??-1)-(lowestPrice(a)??-1),reliability:(a,b)=>b.rating.reliability-a.rating.reliability,power:(a,b)=>b.rating.power-a.rating.power,value:(a,b)=>b.rating.value-a.rating.value,deal:(a,b)=>dealPct(b)-dealPct(a),confidence:(a,b)=>b.confidence-a.confidence};return [...list].sort(sorters[state.sort]||sorters.recommended)}
function renderCatalog(){const cats=categories();$("#categoryFilter").innerHTML=cats.map(c=>`<option ${c===state.category?'selected':''}>${c}</option>`).join('');$("#categoryButtons").innerHTML=cats.map(c=>`<button class="category-button ${c===state.category?'active':''}" onclick="setCategory('${c.replaceAll("'","\\'")}')"><span>${c}</span><span>${c==='All'?compatibleParts().length:compatibleParts().filter(p=>p.category===c).length}</span></button>`).join('');$("#difficultyFilter").value=state.difficulty;$("#maxPriceFilter").value=state.maxPrice;$("#hideUnverified").checked=state.hideUnverified;$("#sortSelect").value=state.sort;const list=filtered();$("#resultCount").textContent=`${list.length} results`;$("#catalogTitle").textContent=state.category==='All'?'Parts for your project':state.category;$("#partGrid").innerHTML=list.length?list.map(card).join(''):`<div class="empty-state"><strong>No catalog matches yet.</strong><p>Try another filter or vehicle. A vehicle record does not mean parts have verified fitment.</p><button class="button secondary" onclick="resetFilters()">Reset filters</button></div>`}
function scoreRow(label,val){return `<div class="score-row"><span>${label}</span><div class="score-track">${val==null?"":`<span style="width:${val*10}%"></span>`}</div><strong>${ratingText(val)}</strong></div>`}

function card(p){const added=state.build.includes(p.id),comp=state.compare.includes(p.id),watch=state.watches.includes(p.id),offer=lowestOffer(p),deal=dealPct(p),inst=installInfo(p);return`<article class="part-card"><div class="part-top"><div><div class="part-brand">${p.brand} · ${p.category}</div><div class="part-name">${p.name}</div></div><div class="score-chip">${ratingText(p.rating.overall)}</div></div><div class="tags">${(p.tags||[]).slice(0,4).map(t=>`<span class="tag">${t}</span>`).join('')}${deal>=2?`<span class="tag deal-tag">${deal.toFixed(0)}% below median</span>`:''}</div><div class="fitment-line"><span class="fit-dot ${fitmentVerified(p)?'':'uncertain'}"></span>${fitmentVerified(p)?"Source lists selected application":"Fitment needs confirmation"}</div><div class="quick-meta"><span>${inst.difficulty} install</span><span>${inst.hours==null?"Time unknown":`~${inst.hours} hr estimate`}</span><span>${sortedOffers(p).length} recent offers</span><span>${p.scoreMetadata?.review_count||0} published reviews</span></div><div class="score-list">${scoreRow('Quality',p.rating.quality)}${scoreRow('Reliability',p.rating.reliability)}${scoreRow(state.goal==='handling'?'Handling':'Performance',state.goal==='handling'?p.rating.handling:p.rating.power)}${scoreRow('Value',p.rating.value)}</div><div class="part-price-row"><div class="price-block"><small>recent observation · ${offer.seller}</small><strong>${money(offer.price)}</strong><div class="offer-count">median ${money(medianPrice(p))}</div></div><div class="card-actions"><button class="icon-button ${watch?'selected':''}" title="${watch?'Unwatch price':'Watch price'}" onclick="toggleWatch('${p.id}')">${watch?'★':'☆'}</button><button class="button secondary small compare-toggle ${comp?'selected':''}" onclick="toggleCompare('${p.id}')">${comp?'Comparing':'Compare'}</button><button class="button secondary small" onclick="showPart('${p.id}')">Details</button><button class="button primary small" onclick="toggleBuild('${p.id}')" aria-pressed="${added}">${added?'✓ Added':'Add to build'}</button></div></div></article>`}
function setCategory(c){state.category=c;renderCatalog()}
function toggleBuild(id){rememberUndo();state.build.includes(id)?state.build=state.build.filter(x=>x!==id):state.build.push(id);if(state.build.includes(id)&&!state.buildMeta[id])state.buildMeta[id]={status:"planned"};saveState();renderCatalog();renderCounts();renderBuild();toast(state.build.includes(id)?'Added to build':'Removed. Use Undo on the build sheet to restore.');if($('#partDialog')?.open)window.showPart(id)}
function toggleCompare(id){if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else{if(state.compare.length>=4)return toast('Compare supports up to 4 parts');state.compare.push(id)}saveState();renderCatalog();renderCounts();renderCompare()}
function toggleWatch(id){state.watches.includes(id)?state.watches=state.watches.filter(x=>x!==id):state.watches.push(id);saveState();renderCatalog();renderCounts();renderPrices();if($("#partDialog")?.open)showPart(id);toast(state.watches.includes(id)?'Price added to watchlist':'Removed from watchlist')}
function renderCounts(){$("#buildNavCount").textContent=state.build.length;$("#compareNavCount").textContent=state.compare.length;$("#priceNavCount").textContent=state.watches.length;$("#heroWatched").textContent=state.watches.length}
function goalLabel(){return goalNames[state.goal]||"Balanced street"}
function renderPrices(){const ps=compatibleParts();const rows=[...ps].sort((a,b)=>dealPct(b)-dealPct(a));const totalOffers=ps.reduce((s,p)=>s+sortedOffers(p).length,0),avgSpread=ps.length?ps.reduce((s,p)=>s+spread(p),0)/ps.length:0,best=[...ps].sort((a,b)=>dealPct(b)-dealPct(a))[0];$("#priceSummary").innerHTML=`<div><span>Tracked catalog</span><strong>${ps.length}</strong></div><div><span>Seller snapshots</span><strong>${totalOffers}</strong></div><div><span>Avg. price spread</span><strong>${money(avgSpread)}</strong></div><div><span>Watched</span><strong>${state.watches.length}</strong></div>`;$("#priceTable").innerHTML=`<div class="price-row header"><div>Part</div><div>Best snapshot</div><div>Seller</div><div>Median</div><div>Spread</div><div>Watch</div><div></div></div>`+rows.map(p=>{const low=lowestOffer(p),d=dealPct(p),watch=state.watches.includes(p.id);return`<div class="price-row"><div class="rank-part"><strong>${p.brand} ${p.name}</strong><small>${p.category}</small></div><div class="metric-cell"><strong>${money(low.price)}</strong><span>${d>=1?`${d.toFixed(0)}% under median`:'best listed'}</span></div><div class="metric-cell"><strong>${low.seller}</strong><span>${low.shipping||'Check shipping'}</span></div><div class="metric-cell"><strong>${money(medianPrice(p))}</strong><span>snapshot median</span></div><div class="metric-cell"><strong>${money(spread(p))}</strong><span>range</span></div><div><button class="icon-button ${watch?'selected':''}" onclick="toggleWatch('${p.id}')">${watch?'★':'☆'}</button></div><div><a class="button secondary small" href="${low.url}" target="_blank" rel="noopener">Check price</a></div></div>`}).join('');$("#bestDealText").textContent=best?`${best.brand} ${best.name} currently has the largest prototype seller spread (${dealPct(best).toFixed(0)}% below its median snapshot).`:'No price data.'}
function renderRankings(){const cats=categories();$("#rankingCategoryFilter").innerHTML=cats.map(c=>`<option ${c===state.rankingCategory?'selected':''}>${c}</option>`).join('');let list=compatibleParts();if(state.rankingCategory!=="All")list=list.filter(p=>p.category===state.rankingCategory);list=[...list].sort((a,b)=>(goalScore(b)??-1)-(goalScore(a)??-1));const avg=list.length?list.reduce((s,p)=>s+p.rating.overall,0)/list.length:0,best=list[0],trusted=[...list].sort((a,b)=>b.confidence-a.confidence)[0];$("#rankingSummary").innerHTML=`<div><span>Goal</span><strong>${goalLabel()}</strong></div><div><span>Top ranked</span><strong>${best?best.brand:'—'}</strong></div><div><span>Catalog avg.</span><strong>${avg.toFixed(1)}</strong></div><div><span>Highest confidence</span><strong>${trusted?trusted.confidence+'%':'—'}</strong></div>`;const topByCategory=[...new Set(compatibleParts().map(p=>p.category))].sort().map(c=>[...compatibleParts().filter(p=>p.category===c)].sort((a,b)=>(goalScore(b)??-1)-(goalScore(a)??-1))[0]).filter(Boolean).slice(0,8);$("#categoryTopPicks").innerHTML=topByCategory.map(p=>`<button class="top-pick-card" onclick="showPart('${p.id}')"><span>${p.category}</span><strong>${p.brand} ${p.name}</strong><small>${ratingText(goalScore(p))} ${goalLabel()} score · ${money(lowestPrice(p))}</small></button>`).join('');$("#rankingTable").innerHTML=`<div class="ranking-row header"><div>Rank</div><div>Part</div><div>Goal score</div><div>Rating</div><div>Reliability</div><div>Price</div><div></div></div>`+list.map((p,i)=>`<div class="ranking-row"><div class="rank-number">#${i+1}</div><div class="rank-part"><strong>${p.brand} ${p.name}</strong><small>${p.category} · ${installInfo(p).difficulty}</small></div><div class="metric-cell"><strong>${ratingText(goalScore(p))}</strong><span>${goalLabel()}</span></div><div class="metric-cell"><strong>${ratingText(p.rating.overall)}</strong><span>overall</span></div><div class="metric-cell"><strong>${ratingText(p.rating.reliability)}</strong><span>reliability</span></div><div class="metric-cell"><strong>${money(lowestPrice(p))}</strong><span>from</span></div><div><button class="button secondary small" onclick="showPart('${p.id}')">View</button></div></div>`).join('')}
function renderCompare(){const ps=state.compare.map(part).filter(Boolean);$("#compareEmpty").style.display=ps.length?'none':'block';$("#compareEmpty").innerHTML=`<strong>No parts selected.</strong><br>Add parts using the Compare button in the catalog.`;$("#clearCompareButton").disabled=!ps.length;if(!ps.length){$("#compareTableWrap").innerHTML='';return}const row=(label,fn)=>`<div class="compare-row" style="--cols:${ps.length}"><div class="compare-cell compare-label">${label}</div>${ps.map(p=>`<div class="compare-cell">${fn(p)}</div>`).join('')}</div>`;$("#compareTableWrap").innerHTML=`<div class="compare-table">${row('Part',p=>`<div class="compare-part-head"><span class="eyebrow">${p.brand}</span><strong>${p.name}</strong><small>${p.category}</small><br><button class="button secondary small" style="margin-top:12px" onclick="toggleCompare('${p.id}')">Remove</button></div>`)}${row('Goal score',p=>`<strong>${ratingText(goalScore(p))}/10</strong><br><small>${goalLabel()}</small>`)}${row('Best price',p=>`<strong>${money(lowestPrice(p))}</strong><br><small>${lowestOffer(p).seller}</small>`)}${row('Median snapshot',p=>`<strong>${money(medianPrice(p))}</strong><br><small>${sortedOffers(p).length} recent offers</small>`)}${row('Install',p=>`<strong>${installInfo(p).difficulty}</strong><br><small>~${installInfo(p).hours} hr</small>`)}${row('Overall',p=>`<strong>${ratingText(p.rating.overall)}/10</strong>`)}${row('Reliability',p=>`<strong>${ratingText(p.rating.reliability)}/10</strong>`)}${row('Power',p=>`<strong>${ratingText(p.rating.power)}/10</strong><br><small>${p.powerImpact?`~+${p.powerImpact} hp`:'supporting mod'}</small>`)}${row('Handling',p=>`<strong>${ratingText(p.rating.handling)}/10</strong>`)}${row('Value',p=>`<strong>${ratingText(p.rating.value)}/10</strong>`)}${row('Confidence',p=>`<strong>${p.confidence}%</strong>`)}${row('Requires',p=>p.requires?.length?p.requires.map(id=>part(id)?.name||id).join('<br>'):'None')}${row('Fitment',p=>p.fitment)}</div>`}
function buildIssues(){const issues=[],selected=new Set(state.build),ps=state.build.map(part).filter(Boolean);ps.forEach(p=>{(p.requires||[]).forEach(req=>{if(!selected.has(req))issues.push({level:'warn',text:`${p.name} requires ${part(req)?.name||req}.`})});(p.conflicts||[]).forEach(conf=>{if(selected.has(conf)&&p.id<conf)issues.push({level:'bad',text:`${p.name} conflicts with ${part(conf)?.name||conf}.`})});if((p.confidence||0)<55)issues.push({level:'info',text:`${p.name} has lower prototype confidence; verify application before purchase.`})});const power=ps.reduce((s,p)=>s+(p.powerImpact||0),0);if(power>=40&&!ps.some(p=>p.category==='Cooling'))issues.push({level:'warn',text:'High estimated power increase without a cooling-system upgrade in the build. This is a prototype planning rule, not a fitment guarantee.'});if(state.goal==='track'&&!ps.some(p=>p.category==='Brakes'))issues.push({level:'info',text:'Track goal selected with no brake upgrade yet.'});if(state.goal==='track'&&!ps.some(p=>p.category==='Tires'))issues.push({level:'info',text:'Track goal selected with no tire upgrade yet.'});return issues}
function recommendedCategories(){return ({power:["Cooling","Drivetrain","Brakes","Tires"],track:["Tires","Brakes","Suspension","Cooling"],handling:["Tires","Suspension","Brakes","Chassis"],reliability:["Maintenance","Cooling","Brakes"],budget:["Maintenance","Tires","Brakes"],balanced:["Tires","Brakes","Suspension","Cooling"]}[state.goal]||[])}
function buildCoverage(){const have=new Set(state.build.map(id=>part(id)?.category).filter(Boolean)),needed=recommendedCategories();return{needed,have,percent:needed.length?Math.round(needed.filter(c=>have.has(c)).length/needed.length*100):100}}
function renderBuild(){renderBuildHeader();const ps=state.build.map(part).filter(Boolean),issues=buildIssues(),coverage=buildCoverage();$("#compatibilityPanel").innerHTML=issues.length?`<div class="compat-card warn"><h3>Build checks</h3><ul>${issues.map(i=>`<li class="issue-${i.level}">${i.text}</li>`).join('')}</ul></div>`:`<div class="compat-card good"><h3>${ps.length?'Build checks look good':'Start your build'}</h3><p>${ps.length?'No known conflicts or missing required supporting modifications are detected in this prototype ruleset.':'Add parts from the catalog. ModPicker will track price, category coverage, install time, dependencies and known conflicts.'}</p></div>`;$("#coveragePanel").innerHTML=`<div class="coverage-head"><div><span class="eyebrow">Build coverage</span><strong>${coverage.percent}% of recommended categories</strong></div><span>${coverage.needed.filter(c=>coverage.have.has(c)).length}/${coverage.needed.length}</span></div><div class="coverage-track"><span style="width:${coverage.percent}%"></span></div><div class="coverage-chips">${coverage.needed.map(c=>`<span class="coverage-chip ${coverage.have.has(c)?'done':''}">${coverage.have.has(c)?'✓ ':''}${c}</span>`).join('')}</div>`;const cats=[...new Set(ps.map(p=>p.category))].sort();$("#buildCategories").innerHTML=ps.length?cats.map(c=>{const arr=ps.filter(p=>p.category===c);return`<div class="build-category"><div class="build-category-head"><strong>${c}</strong><span>${arr.length} part${arr.length!==1?'s':''}</span></div>${arr.map(p=>{const status=state.buildMeta[p.id]?.status||'planned';return`<div class="build-item enhanced"><div><strong>${p.brand} ${p.name}</strong><small>${p.fitment}</small><div class="mini-meta">${installInfo(p).difficulty} · ~${installInfo(p).hours} hr · ${lowestOffer(p).seller}</div></div><div><select class="status-select" onchange="setBuildStatus('${p.id}',this.value)"><option value="planned" ${status==='planned'?'selected':''}>Planned</option><option value="installed" ${status==='installed'?'selected':''}>Installed</option></select></div><div><strong>${money(lowestPrice(p))}</strong><small>observed price</small></div><button class="button danger small" onclick="toggleBuild('${p.id}')">×</button></div>`}).join('')}</div>`}).join(''):`<div class="empty-state">Your build sheet is empty. Add compatible parts from the catalog.</div>`;renderSuggestions();renderBuildSummary()}
function renderBuildHeader(){$("#buildTitle").textContent=`${vehicle().year} ${vehicle().make} ${vehicle().model} build`;$("#buildNameInput").value=state.buildName;$("#budgetInput").value=state.budget||"";$("#laborRateInput").value=state.laborRate||""}
function renderBuildSummary(){const ps=state.build.map(part).filter(Boolean),partsTotal=ps.reduce((s,p)=>s+lowestPrice(p),0),hours=ps.reduce((s,p)=>s+(Number(installInfo(p).hours)||0),0),labor=hours*(Number(state.laborRate)||0),grand=partsTotal+labor,avg=ps.length?ps.reduce((s,p)=>s+p.rating.overall,0)/ps.length:0,power=ps.reduce((s,p)=>s+(p.powerImpact||0),0),conf=ps.length?Math.round(ps.reduce((s,p)=>s+(p.confidence||0),0)/ps.length):0,gs=ps.length?ps.reduce((s,p)=>s+goalScore(p),0)/ps.length:0,budget=Number(state.budget)||0,delta=budget-grand;$("#buildPartsTotal").textContent=money(partsTotal);$("#buildLaborTotal").textContent=money(labor);$("#buildTotal").textContent=money(grand);$("#buildPartCount").textContent=ps.length;$("#buildHours").textContent=ps.length?`${hours.toFixed(1)} hr`:'—';$("#buildAvgRating").textContent=ps.length?avg.toFixed(1):'—';$("#buildPowerImpact").textContent=ps.length?`~+${power} hp`:'—';$("#buildConfidence").textContent=ps.length?`${conf}%`:'—';$("#buildGoalScore").innerHTML=`<span>${goalLabel()} build score</span><strong>${ps.length?gs.toFixed(1)+'/10':'—'}</strong>`;$("#budgetStatus").innerHTML=budget?`<span>${delta>=0?'Budget remaining':'Over budget'}</span><strong class="${delta>=0?'budget-good':'budget-bad'}">${money(Math.abs(delta))}${delta<0?' over':''}</strong>`:`<span>Set a build budget to track remaining spend.</span>`}
function renderSuggestions(){const selected=new Set(state.build),coverage=buildCoverage(),missing=coverage.needed.filter(c=>!coverage.have.has(c));let candidates=compatibleParts().filter(p=>!selected.has(p.id));candidates.sort((a,b)=>{const am=missing.includes(a.category)?1:0,bm=missing.includes(b.category)?1:0;return bm-am||(goalScore(b)??-1)-(goalScore(a)??-1)});$("#buildSuggestions").innerHTML=candidates.slice(0,4).map(p=>`<button class="suggestion-card" onclick="toggleBuild('${p.id}')"><span>${missing.includes(p.category)?'Missing category':'Recommended next'}</span><strong>${p.brand} ${p.name}</strong><small>${p.category} · ${ratingText(goalScore(p))} score · ${money(lowestPrice(p))}</small></button>`).join('')||'<div class="empty-state compact">No additional suggestions.</div>'}
function setBuildStatus(id,status){state.buildMeta[id]={...(state.buildMeta[id]||{}),status};saveState();toast(`${part(id)?.name||'Part'} marked ${status}`)}
function showPart(id){const p=part(id);if(!p)return;const req=p.requires?.length?p.requires.map(x=>part(x)?.name||x).join(', '):'None',rec=partRecommendations(p).length?partRecommendations(p).map(x=>part(x)?.name||x).join(', '):'None',conflicts=p.conflicts?.length?p.conflicts.map(x=>part(x)?.name||x).join(', '):'None',inst=installInfo(p),watch=state.watches.includes(p.id),added=state.build.includes(p.id),alts=compatibleParts().filter(x=>x.category===p.category&&x.id!==p.id).sort((a,b)=>(goalScore(b)??-1)-(goalScore(a)??-1)).slice(0,3);const offers=sortedOffers(p).map(o=>`<div class="seller-row"><div><strong>${o.seller}</strong><small>${o.shipping||'Check shipping'} · ${o.status||'Verify'}</small></div><strong>${money(o.price)}</strong><a class="button secondary small" href="${o.url}" target="_blank" rel="noopener">Check</a></div>`).join('');$("#partDialogContent").innerHTML=`<div class="dialog-hero"><span class="eyebrow">${p.brand} · ${p.category}</span><h2>${p.name}</h2><p>${p.summary}</p><div class="dialog-actions"><button class="button ${watch?'secondary':'primary'}" onclick="toggleWatch('${p.id}')">${watch?'★ Watching price':'☆ Watch price'}</button><button class="button ${added?'secondary':'primary'}" onclick="toggleBuild('${p.id}')">${added?'Remove from build':'Add to build'}</button></div></div><div class="detail-grid"><div><span>Overall</span><strong>${ratingText(p.rating.overall)}/10</strong></div><div><span>${goalLabel()}</span><strong>${ratingText(goalScore(p))}/10</strong></div><div><span>Confidence</span><strong>${p.confidence}%</strong></div><div><span>Install</span><strong>${inst.hours==null?"Unknown":`${inst.difficulty} · ~${inst.hours} hr estimate`}</strong></div></div><div class="detail-section"><h3>Price finder</h3><div class="price-callout"><div><span>Best price observation</span><strong>${money(lowestPrice(p))}</strong></div><div><span>Median snapshot</span><strong>${money(medianPrice(p))}</strong></div><div><span>Seller spread</span><strong>${money(spread(p))}</strong></div></div><div class="seller-list">${offers}</div><p class="fine-print">Observed prices exclude tax and may exclude shipping. Use “Check” to verify price, stock, shipping and exact SKU with the seller.</p></div><div class="detail-section"><h3>Score breakdown</h3>${scoreRow('Quality',p.rating.quality)}${scoreRow('Reliability',p.rating.reliability)}${scoreRow('Power',p.rating.power)}${scoreRow('Handling',p.rating.handling)}${scoreRow('Value',p.rating.value)}</div><div class="two-col-details"><div class="detail-section"><h3>Pros</h3><ul>${(p.pros||[]).map(x=>`<li>${x}</li>`).join('')}</ul></div><div class="detail-section"><h3>Tradeoffs</h3><ul>${(p.cons||[]).map(x=>`<li>${x}</li>`).join('')}</ul></div></div><div class="detail-section"><h3>Fitment & build rules</h3><p>${p.fitment}</p><p><strong>Requires:</strong> ${req}</p><p><strong>Recommended with:</strong> ${rec}</p><p><strong>Conflicts:</strong> ${conflicts}</p></div><div class="detail-section"><h3>Alternatives in ${p.category}</h3><div class="alternative-grid">${alts.map(a=>`<button class="alternative-card" onclick="showPart('${a.id}')"><strong>${a.brand} ${a.name}</strong><span>${ratingText(a.rating.overall)} · ${money(lowestPrice(a))}</span></button>`).join('')||'<span class="muted">No alternatives in this prototype catalog.</span>'}</div></div>`;if(!$("#partDialog").open)$("#partDialog").showModal()}
async function copyText(text,msg){try{await navigator.clipboard.writeText(text);toast(msg)}catch(e){const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();toast(msg)}}
function copyBuild(){const ps=state.build.map(part).filter(Boolean),partsTotal=ps.reduce((s,p)=>s+lowestPrice(p),0),hours=ps.reduce((s,p)=>s+installInfo(p).hours,0),labor=hours*(Number(state.laborRate)||0);const lines=[state.buildName,`${vehicle().year} ${vehicle().make} ${vehicle().model} ${vehicle().trim}`,`Goal: ${goalLabel()}`,"",...ps.map(p=>`- [${state.buildMeta[p.id]?.status==='installed'?'Installed':'Planned'}] ${p.brand} ${p.name} — ${money(lowestPrice(p))} — ${ratingText(p.rating.overall)}/10`),"",`Parts: ${money(partsTotal)}`,`Estimated labor: ${money(labor)} (${hours.toFixed(1)} hr @ ${money(state.laborRate)}/hr)`,`Estimated total: ${money(partsTotal+labor)}`];copyText(lines.join('\n'),"Build summary copied")}
function shareBuild(){const payload={vehicleId:state.vehicleId,goal:state.goal,build:state.build};const url=new URL(location.href);url.searchParams.set("build",btoa(JSON.stringify(payload)));url.hash="";copyText(url.toString(),"Share link copied")}
window.setCategory=setCategory;window.toggleBuild=toggleBuild;window.toggleCompare=toggleCompare;window.toggleWatch=toggleWatch;window.showPart=showPart;window.setBuildStatus=setBuildStatus;


function ratingText(n){return Number.isFinite(n)?n.toFixed(1):'—'}
function selectedFitment(p){return (p.fitments||[]).find(f=>String(f.vehicle_id)===String(state.vehicleId))||null}
function fitmentVerified(p){const f=selectedFitment(p);return Boolean(f&&f.fitment_status==='verified'&&f.source_url)}
function resetFilters(){state.query='';state.category='All';state.maxPrice='Any';state.difficulty='All';state.hideUnverified=false;$('#searchInput').value='';renderCatalog()}
function persistGarage(){state.garage??={};state.garage[state.vehicleId]={build:[...state.build],buildMeta:structuredClone(state.buildMeta),buildName:state.buildName,budget:state.budget,laborRate:state.laborRate,goal:state.goal};}
function switchVehicle(id){if(!DATA.vehicles.some(v=>v.id===id))return;persistGarage();state.vehicleId=id;Object.assign(state,{build:[],buildMeta:{},buildName:'My build',budget:5000,laborRate:0,goal:'balanced'},structuredClone(state.garage[id]||{}));state.category='All';state.rankingCategory='All';state.compare=[];state.query='';$('#searchInput').value='';saveState();renderAll();toast('Vehicle changed. Your other builds are saved.');}
let undoBuild=null;
function rememberUndo(){undoBuild={vehicleId:state.vehicleId,build:[...state.build],buildMeta:structuredClone(state.buildMeta)}}
function restoreBuild(){if(!undoBuild||undoBuild.vehicleId!==state.vehicleId)return toast('Nothing to undo for this vehicle');state.build=undoBuild.build;state.buildMeta=undoBuild.buildMeta;undoBuild=null;saveState();renderAll();toast('Build restored')}
function setBuildField(id,field,value){const m=state.buildMeta[id]??={status:'planned'};if(field==='quantity')m[field]=Math.max(1,Math.min(100,Math.floor(Number(value)||1)));else if(field==='paid')m[field]=value===''?null:Math.max(0,Number(value)||0);else m[field]=String(value).slice(0,1000);saveState();renderBuildSummary();const total=document.querySelector(`[data-part="${id}"] .line-total`);if(total)total.textContent=money(itemCost(part(id)).total)}
function itemCost(p){const m=state.buildMeta[p.id]||{};const offer=sortedOffers(p).find(o=>o.url===m.sellerUrl)||lowestOffer(p);const unit=m.paid!=null?Number(m.paid):offer.price;return {quantity:m.quantity||1,unit,total:unit==null?null:unit*(m.quantity||1),offer}}
function buildTotals(){const ps=state.build.map(part).filter(Boolean);let subtotal=0,unknown=0,hours=0,unknownHours=0;for(const p of ps){const c=itemCost(p);if(c.total==null)unknown++;else subtotal+=c.total;if(p.install?.hours!=null)hours+=Number(p.install.hours)*c.quantity;else unknownHours++}return{ps,subtotal,unknown,hours,unknownHours,labor:hours*(Number(state.laborRate)||0)}}
function buildIssues(){const issues=[],selected=new Set(state.build),pairs=new Set();for(const p of state.build.map(part).filter(Boolean)){for(const req of p.requires||[])if(!selected.has(req))issues.push({level:'warn',text:`${p.name} lists ${part(req)?.name||req} as a supporting part. Confirm requirements.`});for(const conflict of p.conflicts||[])if(selected.has(conflict)){const key=[p.id,conflict].sort().join('|');if(!pairs.has(key)){pairs.add(key);issues.push({level:'bad',text:`${p.name} conflicts with ${part(conflict)?.name||conflict}.`})}}if(!fitmentVerified(p))issues.push({level:'info',text:`Confirm exact fitment for ${p.name}.`});}return issues}
function renderBuild(){renderBuildHeader();const ps=state.build.map(part).filter(Boolean),issues=buildIssues(),coverage=buildCoverage();$('#compatibilityPanel').innerHTML=`<div class="compat-card ${issues.length?'warn':'good'}"><h3>${ps.length?'Fitment & supporting parts':'Plan your next upgrade'}</h3>${issues.length?`<ul>${issues.map(i=>`<li class="issue-${i.level}">${i.text}</li>`).join('')}</ul>`:'<p>Add parts, compare sellers, and track each purchase. Checks cover recorded rules only; they are not a fitment guarantee.</p>'}</div>`;$('#coveragePanel').innerHTML=`<div class="coverage-head"><div><span class="eyebrow">Explore your ${goalLabel().toLowerCase()} plan</span><strong>Suggested categories</strong></div><button class="button secondary small" onclick="restoreBuild()" ${undoBuild?.vehicleId===state.vehicleId?'':'disabled'}>Undo last change</button></div><div class="coverage-chips">${coverage.needed.map(c=>`<button class="coverage-chip ${coverage.have.has(c)?'done':''}" onclick="state.category='${c}';renderCatalog();route('catalog')">${coverage.have.has(c)?'✓ ': '+ '}${c}</button>`).join('')}</div><p class="fine-print">Suggestions are optional. More parts do not necessarily make a better build.</p>`;
$('#buildCategories').innerHTML=ps.length?[...new Set(ps.map(p=>p.category))].sort().map(cat=>`<section class="build-category"><div class="build-category-head"><strong>${cat}</strong></div>${ps.filter(p=>p.category===cat).map(p=>{const m=state.buildMeta[p.id]||{},c=itemCost(p),offers=sortedOffers(p);return `<article class="build-item polished" data-part="${p.id}"><div class="build-item-title"><button class="text-button" onclick="showPart('${p.id}')">${p.brand} ${p.name}</button><small>${fitmentVerified(p)?'Application listed by source':'Exact fitment needs confirmation'}</small></div><strong class="line-total">${money(c.total)}</strong><button class="button danger small" aria-label="Remove ${p.name}" onclick="toggleBuild('${p.id}')">Remove</button><div class="item-fields"><label>Status<select onchange="setBuildField('${p.id}','status',this.value)">${['planned','ordered','installed'].map(x=>`<option value="${x}" ${m.status===x?'selected':''}>${x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select></label><label>Quantity<input aria-label="Quantity for ${p.name}" type="number" min="1" max="100" value="${c.quantity}" onchange="setBuildField('${p.id}','quantity',this.value)"></label><label>Unit cost override ($)<input type="number" min="0" step="0.01" placeholder="${c.unit??'Unknown'}" value="${m.paid??''}" onchange="setBuildField('${p.id}','paid',this.value)"></label><label>Seller<select onchange="setBuildField('${p.id}','sellerUrl',this.value)"><option value="">Lowest recent item price</option>${offers.map(o=>`<option value="${MP_TEXT(o.url)}" ${m.sellerUrl===o.url?'selected':''}>${o.seller} · ${money(o.price)}</option>`).join('')}</select></label></div><label class="item-note">Notes<input maxlength="1000" placeholder="Part number, options, install notes…" value="${MP_TEXT(m.note||'')}" onchange="setBuildField('${p.id}','note',this.value)"></label>${c.offer.url!=='#'?`<a class="seller-link" href="${MP_TEXT(c.offer.url)}" target="_blank" rel="noopener">${c.offer.price==null?'Find a current quote':'Check seller price'} ↗</a>`:''}</article>`}).join('')}</section>`).join(''):'<div class="empty-state"><strong>Your build starts here.</strong><p>Choose parts from the catalog. Your selections save automatically for each vehicle in this browser.</p><button class="button primary" onclick="route(\'catalog\')">Browse parts</button></div>';renderSuggestions();renderBuildSummary()}
function renderBuildSummary(){const t=buildTotals(),grand=t.subtotal+t.labor,budget=Number(state.budget)||0,delta=budget-grand;$('#buildPartsTotal').textContent=money(t.subtotal);$('#buildLaborTotal').textContent=money(t.labor);$('#buildTotal').textContent=money(grand)+(t.unknown||t.unknownHours&&state.laborRate?' + unknowns':'');$('#buildPartCount').textContent=t.ps.reduce((n,p)=>n+itemCost(p).quantity,0);$('#buildHours').textContent=t.unknownHours?'Estimate incomplete':`${t.hours.toFixed(1)} hr`;$('#buildAvgRating').textContent=`${t.ps.filter(p=>state.buildMeta[p.id]?.status==='ordered').length} ordered`;$('#buildPowerImpact').textContent=`${t.ps.filter(p=>state.buildMeta[p.id]?.status==='installed').length} installed`;$('#buildConfidence').textContent=`${t.ps.filter(fitmentVerified).length}/${t.ps.length} listed`;
$('#buildGoalScore').innerHTML=`<span>${t.unknown} unpriced item${t.unknown===1?'':'s'} · tax & shipping extra</span>`;$('#budgetStatus').innerHTML=budget?`<span>${delta>=0?'Remaining before unknown costs':'Over budget'}</span><strong class="${delta>=0?'budget-good':'budget-bad'}">${money(Math.abs(delta))}</strong>`:'<span>Set a budget to track your plan.</span>'}
function renderSuggestions(){const selected=new Set(state.build),missing=buildCoverage().needed.filter(c=>!buildCoverage().have.has(c));const ps=compatibleParts().filter(p=>!selected.has(p.id)&&!(p.conflicts||[]).some(id=>selected.has(id))&&!state.build.some(id=>part(id)?.conflicts?.includes(p.id))).sort((a,b)=>Number(missing.includes(b.category))-Number(missing.includes(a.category))||Number(fitmentVerified(b))-Number(fitmentVerified(a)));$('#buildSuggestions').innerHTML=ps.slice(0,4).map(p=>`<button class="suggestion-card" onclick="showPart('${p.id}')"><span>Explore ${p.category}</span><strong>${p.brand} ${p.name}</strong><small>${money(lowestPrice(p))} · ${fitmentVerified(p)?'Application listed':'Confirm fitment'} · View details</small></button>`).join('')}
function renderRankings(){const cats=categories();$('#rankingCategoryFilter').innerHTML=cats.map(c=>`<option ${c===state.rankingCategory?'selected':''}>${c}</option>`).join('');let ps=compatibleParts().filter(p=>state.rankingCategory==='All'||p.category===state.rankingCategory);const rated=ps.filter(p=>Number.isFinite(p.rating.overall)).sort((a,b)=>b.rating.overall-a.rating.overall);$('#rankingSummary').innerHTML=`<div><span>Rated products</span><strong>${rated.length}/${ps.length}</strong></div><div><span>Basis</span><strong>Published reviews</strong></div><div><span>Missing evidence</span><strong>Not rated</strong></div>`;$('#categoryTopPicks').innerHTML='<p class="fine-print">Ratings reflect published owner reviews, normalized to 10. They do not measure horsepower, reliability or your build goal. Compare products within the same category. Multiple sellers may syndicate reviews.</p>';$('#rankingTable').innerHTML=rated.length?`<div class="ranking-row header"><div>#</div><div>Part</div><div>Owner rating</div><div>Reviews</div><div>Sources</div><div>Item price</div><div></div></div>`+rated.map((p,i)=>`<div class="ranking-row"><div>${i+1}</div><div><strong>${p.brand} ${p.name}</strong><small>${p.category}</small></div><div>${ratingText(p.rating.overall)}/10</div><div>${p.scoreMetadata.review_count}</div><div>${p.scoreMetadata.sourceCount}</div><div>${money(lowestPrice(p))}</div><button class="button secondary small" onclick="showPart('${p.id}')">Evidence</button></div>`).join(''):'<div class="empty-state"><strong>No published review ratings in this selection yet.</strong><p>Scheduled collectors will add ratings when an identified product page publishes review data. Source-link counts never substitute for product ratings.</p></div>'}
function renderPrices(){const ps=compatibleParts(),priced=ps.filter(p=>lowestPrice(p)!=null);$('#priceSummary').innerHTML=`<div><span>With recent prices</span><strong>${priced.length}/${ps.length}</strong></div><div><span>Recent offers</span><strong>${ps.reduce((n,p)=>n+sortedOffers(p).length,0)}</strong></div><div><span>Bookmarked here</span><strong>${state.watches.length}</strong></div>`;$('#bestDealText').textContent='Observed USD item prices from the past 7 days. Shipping and tax are extra. Stars bookmark parts in this browser; they do not send alerts.';$('#priceTable').innerHTML=priced.length?`<div class="price-row header"><div>Part</div><div>Item price</div><div>Seller</div><div>Checked</div><div>Offers</div><div>Save</div><div></div></div>`+priced.sort((a,b)=>lowestPrice(a)-lowestPrice(b)).map(p=>{const o=lowestOffer(p);return `<div class="price-row"><div><strong>${p.brand} ${p.name}</strong><small>${p.category}</small></div><strong>${money(o.price)}</strong><div>${o.seller}<small>${o.shipping}</small></div><div>${new Date(o.retrieved_at).toLocaleDateString()}</div><div>${sortedOffers(p).length}</div><button class="icon-button" aria-label="Bookmark ${p.name}" onclick="toggleWatch('${p.id}')">${state.watches.includes(p.id)?'★':'☆'}</button><a class="button secondary small" href="${MP_TEXT(o.url)}" target="_blank" rel="noopener">Check seller</a></div>`}).join(''):'<div class="empty-state">No recent price observations for this vehicle. Open a part’s details for product links.</div>'}
function copyBuild(){const t=buildTotals();copyText([state.buildName,`${vehicle().year} ${vehicle().make} ${vehicle().model}`,`Goal: ${goalLabel()}`,'',...t.ps.map(p=>{const m=state.buildMeta[p.id]||{},c=itemCost(p);return `${m.status||'planned'} | ${c.quantity} × ${p.brand} ${p.name} | ${money(c.total)}${m.note?' | '+m.note:''}`}),'',`Known parts subtotal: ${money(t.subtotal)}`,`Estimated labor: ${money(t.labor)}`,`${t.unknown} items unpriced; ${t.unknownHours} install times unknown. Tax and shipping extra.`].join('\n'),'Build summary copied')}
function buildPayload(){return {version:3,vehicleId:state.vehicleId,goal:state.goal,build:state.build,buildMeta:state.buildMeta,buildName:state.buildName,budget:state.budget,laborRate:state.laborRate}}
function shareBuild(){const u=new URL(location.href);u.searchParams.set('build',btoa(String.fromCharCode(...new TextEncoder().encode(JSON.stringify(buildPayload())))));u.hash='';copyText(u.toString(),'Share link copied, including notes and costs')}
function acceptBuild(p){if(!p||!Array.isArray(p.build)||p.build.length>200||!DATA.vehicles.some(v=>v.id===p.vehicleId))throw new Error('Invalid vehicle or build');state.vehicleId=p.vehicleId;state.build=[...new Set(p.build.filter(id=>typeof id==='string'&&part(id)))];state.goal=goalNames[p.goal]?p.goal:'balanced';state.buildName=String(p.buildName||'Shared build').slice(0,100);state.budget=Math.max(0,Math.min(1e7,Number(p.budget)||0));state.laborRate=Math.max(0,Math.min(1e4,Number(p.laborRate)||0));state.buildMeta={};for(const id of state.build){const m=p.buildMeta?.[id]||{};state.buildMeta[id]={status:['planned','ordered','installed'].includes(m.status)?m.status:'planned',quantity:Math.max(1,Math.min(100,Math.floor(Number(m.quantity)||1))),paid:m.paid==null?null:Math.max(0,Math.min(1e7,Number(m.paid)||0)),note:String(m.note||'').slice(0,1000),sellerUrl:MP_URL(m.sellerUrl)}}state.route='build'}
function parseShare(){const token=new URLSearchParams(location.search).get('build');if(!token)return;try{if(token.length>100000)throw new Error('Too large');persistGarage();acceptBuild(JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(token),c=>c.charCodeAt(0)))));toast('Shared build loaded')}catch(e){toast('Unable to load this build link. Your saved build is unchanged.')}}
function exportBuild(){const blob=new Blob([JSON.stringify(buildPayload(),null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='modpicker-build.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importBuild(file){if(!file)return;try{if(file.size>100000)throw new Error('Too large');const payload=JSON.parse(await file.text());rememberUndo();persistGarage();acceptBuild(payload);saveState();renderAll();route('build');toast('Build imported')}catch(e){toast('Invalid build file. Choose a ModPicker JSON export.')}}


function card(p){const added=state.build.includes(p.id),comp=state.compare.includes(p.id),o=lowestOffer(p),sources=p.liveSources||[],reviews=p.scoreMetadata?.review_count||0;return `<article class="part-card"><div class="part-top"><div><div class="part-brand">${p.brand} · ${p.category}</div><div class="part-name">${p.name}</div></div><div class="score-chip ${p.rating.overall==null?'unrated':''}" title="Published owner rating out of 10">${ratingText(p.rating.overall)}</div></div><div class="tags"><span class="tag">${p.rating.overall==null?'Not rated':`${reviews} published reviews`}</span>${p.mpn?`<span class="tag">${p.mpn}</span>`:''}</div><div class="fitment-line"><span class="fit-dot ${fitmentVerified(p)?'':'uncertain'}"></span>${fitmentVerified(p)?'Source lists selected application':'Confirm exact fitment'}</div><div class="evidence-facts"><div><span>Product rating</span><strong>${p.rating.overall==null?'Awaiting review data':`${ratingText(p.rating.overall)} / 10`}</strong></div><div><span>Research links</span><strong>${new Set(sources.map(s=>s.url)).size}</strong></div><div><span>Recent USD offers</span><strong>${sortedOffers(p).length}</strong></div></div><div class="part-price-row"><div class="price-block"><small>${o.price==null?'No recent price':o.seller}</small><strong>${money(o.price)}</strong><div class="offer-count">${o.retrieved_at?`Checked ${new Date(o.retrieved_at).toLocaleDateString()}`:'Check product source'}</div></div><div class="card-actions"><button class="icon-button ${state.watches.includes(p.id)?'selected':''}" aria-label="Bookmark ${p.name}" onclick="toggleWatch('${p.id}')">${state.watches.includes(p.id)?'★':'☆'}</button><button class="button secondary small ${comp?'selected':''}" onclick="toggleCompare('${p.id}')">${comp?'Comparing':'Compare'}</button><button class="button secondary small" onclick="showPart('${p.id}')">Details</button><button class="button primary small" aria-pressed="${added}" onclick="toggleBuild('${p.id}')">${added?'✓ Added':'Add to build'}</button></div></div></article>`}
function renderCompare(){const ps=state.compare.map(part).filter(Boolean);$('#compareEmpty').style.display=ps.length?'none':'block';$('#compareEmpty').innerHTML='<strong>Select up to four parts from the catalog.</strong>';$('#clearCompareButton').disabled=!ps.length;if(!ps.length){$('#compareTableWrap').innerHTML='';return}const row=(name,fn)=>`<div class="compare-row" style="--cols:${ps.length}"><div class="compare-cell compare-label">${name}</div>${ps.map(p=>`<div class="compare-cell">${fn(p)}</div>`).join('')}</div>`;$('#compareTableWrap').innerHTML=`<div class="compare-table">${row('Part',p=>`<strong>${p.brand} ${p.name}</strong><br><small>${p.category}</small><br><button class="button secondary small" onclick="toggleCompare('${p.id}')">Remove</button>`)}${row('Recent item price',p=>`${money(lowestPrice(p))}<br><small>${lowestOffer(p).seller}</small>`)}${row('Published owner rating',p=>p.rating.overall==null?'Not rated':`${ratingText(p.rating.overall)}/10 · ${p.scoreMetadata.review_count} reviews`)}${row('Fitment',p=>fitmentVerified(p)?'Application listed by source':'Needs exact fitment confirmation')}${row('Part number',p=>p.mpn||'Not established')}${row('Install estimate',p=>p.install?.hours?`${p.install.difficulty} · ~${p.install.hours} hr (planning estimate)`:'Unknown')}${row('Sources',p=>`${new Set((p.liveSources||[]).map(s=>s.url)).size} links`)}${row('Supporting parts',p=>(p.requires||[]).map(id=>part(id)?.name||id).join(', ')||'No requirements recorded')}${row('Research',p=>`<button class="button secondary small" onclick="showPart('${p.id}')">View sources</button>`)}</div>`}
/* Hierarchical car selection and platform/engine browsing. */
state.browseMode=state.browseMode||'vehicle';
state.platformId=state.platformId||'';
state.platformApplicationId=state.platformApplicationId||'';
DATA.platforms=Array.isArray(DATA.platforms)?DATA.platforms:[];
function escText(value){return typeof MP_TEXT==='function'?MP_TEXT(value):String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function allVehicleRecords(){return (DATA.vehicles||[]).filter(v=>v&&v.id&&v.make&&v.model&&Number.isFinite(Number(v.year)));}
function vehiclePartCount(id){return DATA.parts.filter(p=>(p.vehicles||[]).includes(id)).length}
function distinctValues(values){return [...new Set(values.filter(v=>v!==undefined&&v!==null&&String(v)!==''))]}
function sameText(a,b){return String(a??'').trim().toLowerCase()===String(b??'').trim().toLowerCase()}
function distinctTextValues(values){const seen=new Map();for(const value of values){if(value===undefined||value===null||String(value)==='')continue;const key=String(value).trim().toLowerCase();if(!seen.has(key))seen.set(key,String(value).trim())}return [...seen.values()]}
function carMakes(){return distinctTextValues(allVehicleRecords().map(v=>v.make)).sort((a,b)=>String(a).localeCompare(String(b)))}
function carModels(make){const models=distinctTextValues(allVehicleRecords().filter(v=>sameText(v.make,make)).map(v=>v.model));const partsFor=model=>allVehicleRecords().filter(v=>sameText(v.make,make)&&sameText(v.model,model)).reduce((n,v)=>n+vehiclePartCount(v.id),0);return models.sort((a,b)=>Number(partsFor(b)>0)-Number(partsFor(a)>0)||String(a).localeCompare(String(b)))}
function carYears(make,model){return distinctValues(allVehicleRecords().filter(v=>sameText(v.make,make)&&sameText(v.model,model)).map(v=>Number(v.year))).sort((a,b)=>b-a)}
function carVariants(make,model,year){return allVehicleRecords().filter(v=>sameText(v.make,make)&&sameText(v.model,model)&&Number(v.year)===Number(year)).sort((a,b)=>vehiclePartCount(b.id)-vehiclePartCount(a.id)||String(a.trim).localeCompare(String(b.trim)))}
function optionMarkup(value,label,selected=false){return `<option value="${escText(value)}" ${selected?'selected':''}>${escText(label)}</option>`}
function preferredVehicle(make,model,year,variantId){const rows=carVariants(make,model,year);return rows.find(v=>v.id===variantId)||rows.find(v=>vehiclePartCount(v.id)>0)||rows[0]||null}
function activePlatform(){return DATA.platforms.find(p=>p.id===state.platformId)||DATA.platforms[0]||null}
function platformMakes(){return distinctValues(DATA.platforms.map(p=>p.make)).sort((a,b)=>String(a).localeCompare(String(b)))}
function platformsForMake(make){return DATA.platforms.filter(p=>p.make===make).sort((a,b)=>String(a.display_name||a.name).localeCompare(String(b.display_name||b.name)))}
function platformApplications(platform){if(!platform)return[];return platform.vehicle_ids.map(id=>allVehicleRecords().find(v=>v.id===id)).filter(Boolean).sort((a,b)=>vehiclePartCount(b.id)-vehiclePartCount(a.id)||Number(a.year)-Number(b.year))}
function platformParts(platform){if(!platform)return[];const ids=new Set(platform.vehicle_ids||[]),allow=new Set(platform.categories||[]);return DATA.parts.filter(p=>{const explicit=(p.platform_ids||[]).includes(platform.id);const linked=(p.vehicles||[]).some(id=>ids.has(id));return (explicit||linked)&&(!allow.size||allow.has(p.category))})}
function browseScope(){return state.browseMode==='platform'?'platform':'vehicle'}
function setBrowseMode(mode){const next=mode==='platform'?'platform':'vehicle';if(state.browseMode===next)return;state.browseMode=next;if(next==='platform'){const v=vehicle();const match=DATA.platforms.find(p=>(p.vehicle_ids||[]).includes(v.id))||DATA.platforms[0];state.platformId=match?.id||'';state.platformApplicationId=v.id}else{state.platformApplicationId=''};state.category='All';state.rankingCategory='All';state.query='';$('#searchInput').value='';saveState();renderAll();toast(next==='platform'?'Browsing engine and platform parts':'Browsing exact car parts')}
function selectCarLevel(level,value){const v=vehicle();let make=v.make,model=v.model,year=Number(v.year),variant=v.id;if(level==='make'){make=value;model=carModels(make)[0]||'';year=carYears(make,model).find(y=>carVariants(make,model,y).some(x=>vehiclePartCount(x.id)>0))||carYears(make,model)[0]||'';variant=''}else if(level==='model'){model=value;year=carYears(make,model).find(y=>carVariants(make,model,y).some(x=>vehiclePartCount(x.id)>0))||carYears(make,model)[0]||'';variant=''}else if(level==='year'){year=Number(value);variant=''}else if(level==='variant'){variant=value}const chosen=preferredVehicle(make,model,year,variant);if(chosen)switchVehicle(chosen.id)}
function selectPlatformLevel(level,value){if(level==='make'){const ps=platformsForMake(value);if(ps[0]){switchPlatform(ps[0].id);return}}else if(level==='platform'){switchPlatform(value);return}else if(level==='application'){state.platformApplicationId=value;if(value&&value!==state.vehicleId){switchVehicle(value);return}}const platform=activePlatform();const apps=platformApplications(platform);if(platform&&!state.platformApplicationId)state.platformApplicationId=apps[0]?.id||'';if(platform&&state.platformApplicationId&&!apps.some(v=>v.id===state.platformApplicationId))state.platformApplicationId=apps[0]?.id||'';state.category='All';state.rankingCategory='All';saveState();renderAll()}
function switchPlatform(id){state.platformId=id;const apps=platformApplications(activePlatform());const next=apps.find(v=>v.id===state.vehicleId)?.id||apps[0]?.id||'';state.platformApplicationId=next;if(next&&next!==state.vehicleId){switchVehicle(next);return}state.category='All';state.rankingCategory='All';saveState();renderAll();toast(`${activePlatform()?.display_name||'Platform'} selected`)}
function renderCarSelectors(v){const make=v.make,model=v.model,year=Number(v.year);const makeRows=carMakes();$('#makeSelect').innerHTML=makeRows.map(x=>optionMarkup(x,x,sameText(x,make))).join('');const models=carModels(make);$('#modelSelect').innerHTML=models.map(x=>optionMarkup(x,x,sameText(x,model))).join('');const years=carYears(make,model);$('#yearSelect').innerHTML=years.map(x=>optionMarkup(x,x,x===year)).join('');const variants=carVariants(make,model,year);$('#variantSelect').innerHTML=variants.map(x=>optionMarkup(x.id,`${x.trim||'Unspecified'}${x.engine&&x.engine!=='Not specified'?` · ${x.engine}`:''}${vehiclePartCount(x.id)?` · ${vehiclePartCount(x.id)} parts`:''}`,x.id===v.id)).join('')||optionMarkup(v.id,v.trim||'Unspecified',true)}
function renderPlatformSelectors(){const current=activePlatform(),make=current?.make||platformMakes()[0]||'';const makeRows=platformMakes();$('#platformMakeSelect').innerHTML=makeRows.map(x=>optionMarkup(x,x,x===make)).join('');const ps=platformsForMake(make);if(!ps.some(p=>p.id===state.platformId))state.platformId=ps[0]?.id||'';const platform=activePlatform();$('#platformSelect').innerHTML=ps.map(x=>optionMarkup(x.id,x.display_name||x.name,x.id===state.platformId)).join('');const apps=platformApplications(platform);if(!apps.some(v=>v.id===state.platformApplicationId))state.platformApplicationId=apps.find(v=>v.id===state.vehicleId)?.id||apps[0]?.id||'';$('#platformApplicationSelect').innerHTML=apps.map(x=>optionMarkup(x.id,`${x.year} ${x.make} ${x.model} ${x.trim} · ${vehiclePartCount(x.id)} catalog parts`,x.id===state.platformApplicationId)).join('')||optionMarkup('', 'Any listed application',true)}
function renderVehicle(){const v=vehicle();const platform=activePlatform();$('#vehicleModeButton').classList.toggle('active',state.browseMode!=='platform');$('#platformModeButton').classList.toggle('active',state.browseMode==='platform');$('#vehicleModeButton').setAttribute('aria-selected',String(state.browseMode!=='platform'));$('#platformModeButton').setAttribute('aria-selected',String(state.browseMode==='platform'));$('#vehicleSelectors').hidden=state.browseMode==='platform';$('#platformSelectors').hidden=state.browseMode!=='platform';if(state.browseMode==='platform'){renderPlatformSelectors();$('#vehicleName').textContent=platform?.display_name||'Select an engine or platform';$('#fitmentSummary').textContent=`${platform?.name||'Platform'} · ${platformParts(platform).length} related parts · confirm exact application`}else{renderCarSelectors(v);$('#vehicleName').textContent=`${v.year} ${v.make} ${v.model} ${v.trim}`;$('#fitmentSummary').textContent=`${v.chassis} · ${v.engine} · ${vehiclePartCount(v.id)} catalog parts`}$('#goalSelect').value=state.goal;$('#vehicleBadges').innerHTML=(state.browseMode==='platform'?(platform?.aliases||[]):(v.tags||[])).map(t=>`<span class="badge">${escText(t)}</span>`).join('');const cp=compatibleParts();$('#heroCompatible').textContent=cp.length;$('#heroCategories').textContent=new Set(cp.map(p=>p.category)).size;$('#heroOffers').textContent=cp.reduce((n,p)=>n+sortedOffers(p).length,0);$('#heroWatched').textContent=state.watches.length}
function compatibleParts(){return state.browseMode==='platform'?platformParts(activePlatform()):DATA.parts.filter(p=>(p.vehicles||[]).includes(state.vehicleId))}
function fitmentLabel(p){const f=selectedFitment(p);if(state.browseMode==='platform'&&!fitmentVerified(p))return f?.fitment_status==='probable'?'Platform range match · confirm exact SKU':'Platform-related result · confirm exact vehicle';if(f?.fitment_status==='verified'&&f.rule_id)return 'Source range includes selected application';if(f?.fitment_status==='verified')return 'Source lists selected application';if(f?.fitment_status==='probable'&&f.rule_id)return 'Source range match · confirm exact SKU';return 'Confirm exact fitment'}
function fitmentVerified(p){const f=selectedFitment(p);return Boolean(f&&f.fitment_status==='verified'&&f.source_url)}
function loadState(){try{const raw=localStorage.getItem('modpicker-state-v2')||localStorage.getItem('modpicker-state');if(raw)Object.assign(state,JSON.parse(raw))}catch(e){console.warn('State load failed',e)}state.buildMeta=state.buildMeta||{};state.watches=state.watches||[];state.compare=state.compare||[];state.build=Array.isArray(state.build)?state.build:[];state.garage=state.garage||{};state.browseMode=state.browseMode==='platform'?'platform':'vehicle';state.platformId=String(state.platformId||'');state.platformApplicationId=String(state.platformApplicationId||'');if(!DATA.vehicles.some(v=>v.id===state.vehicleId))state.vehicleId=DATA.vehicles[0]?.id}
function saveState(){persistGarage();try{localStorage.setItem('modpicker-state-v2',JSON.stringify({garage:state.garage,vehicleId:state.vehicleId,goal:state.goal,build:state.build,compare:state.compare,watches:state.watches,buildMeta:state.buildMeta,budget:state.budget,laborRate:state.laborRate,buildName:state.buildName,route:state.route,browseMode:state.browseMode,platformId:state.platformId,platformApplicationId:state.platformApplicationId}))}catch(e){toast('Browser storage unavailable. Export your build to keep it.')}}
function switchVehicle(id){if(!DATA.vehicles.some(v=>v.id===id))return;persistGarage();state.vehicleId=id;Object.assign(state,{build:[],buildMeta:{},buildName:'My build',budget:5000,laborRate:0,goal:'balanced'},structuredClone(state.garage[id]||{}));state.category='All';state.rankingCategory='All';state.compare=[];state.query='';$('#searchInput').value='';saveState();renderAll();toast('Vehicle changed. Your other builds are saved.')}
function bind(){
$('#vehicleModeButton').addEventListener('click',()=>setBrowseMode('vehicle'));$('#platformModeButton').addEventListener('click',()=>setBrowseMode('platform'));
$('#makeSelect').addEventListener('change',e=>selectCarLevel('make',e.target.value));$('#modelSelect').addEventListener('change',e=>selectCarLevel('model',e.target.value));$('#yearSelect').addEventListener('change',e=>selectCarLevel('year',e.target.value));$('#variantSelect').addEventListener('change',e=>selectCarLevel('variant',e.target.value));
$('#platformMakeSelect').addEventListener('change',e=>selectPlatformLevel('make',e.target.value));$('#platformSelect').addEventListener('change',e=>selectPlatformLevel('platform',e.target.value));$('#platformApplicationSelect').addEventListener('change',e=>selectPlatformLevel('application',e.target.value));
$('#goalSelect').addEventListener('change',e=>{state.goal=e.target.value;saveState();renderAll()});$('#searchInput').addEventListener('input',e=>{state.query=e.target.value;renderCatalog()});$('#categoryFilter').addEventListener('change',e=>{state.category=e.target.value;renderCatalog()});$('#difficultyFilter').addEventListener('change',e=>{state.difficulty=e.target.value;renderCatalog()});$('#maxPriceFilter').addEventListener('change',e=>{state.maxPrice=e.target.value;renderCatalog()});$('#sortSelect').addEventListener('change',e=>{state.sort=e.target.value;renderCatalog()});$('#hideUnverified').addEventListener('change',e=>{state.hideUnverified=e.target.checked;renderCatalog()});$('#rankingCategoryFilter').addEventListener('change',e=>{state.rankingCategory=e.target.value;renderRankings()});$('#budgetInput').addEventListener('input',e=>{state.budget=Math.max(0,Number(e.target.value)||0);saveState();renderBuildSummary()});$('#laborRateInput').addEventListener('input',e=>{state.laborRate=Math.max(0,Number(e.target.value)||0);saveState();renderBuildSummary()});$('#buildNameInput').addEventListener('input',e=>{state.buildName=e.target.value||'My build';saveState();renderBuildHeader()});$$('[data-route]').forEach(el=>el.addEventListener('click',ev=>{ev.preventDefault();route(el.dataset.route)}));$('#mobileMenuButton').addEventListener('click',()=>$('.main-nav').classList.toggle('open'));$('#dialogClose').addEventListener('click',()=>$('#partDialog').close());$('#clearBuildButton').addEventListener('click',()=>{rememberUndo();state.build=[];state.buildMeta={};saveState();renderAll();toast('Build cleared. Use Undo to restore it.')});$('#copyBuildButton').addEventListener('click',copyBuild);$('#shareBuildButton').addEventListener('click',shareBuild);$('#clearCompareButton').addEventListener('click',()=>{state.compare=[];saveState();renderAll();toast('Comparison cleared')})}
function card(p){const added=state.build.includes(p.id),comp=state.compare.includes(p.id),o=lowestOffer(p),sources=p.liveSources||[],reviews=p.scoreMetadata?.review_count||0;return `<article class="part-card"><div class="part-top"><div><div class="part-brand">${escText(p.brand)} · ${escText(p.category)}</div><div class="part-name">${escText(p.name)}</div></div><div class="score-chip ${p.rating.overall==null?'unrated':''}" title="Published owner rating out of 10">${ratingText(p.rating.overall)}</div></div><div class="tags"><span class="tag">${p.rating.overall==null?'Not rated':`${reviews} published reviews`}</span>${p.mpn?`<span class="tag">${escText(p.mpn)}</span>`:''}</div><div class="fitment-line"><span class="fit-dot ${fitmentVerified(p)?'':'uncertain'}"></span>${escText(fitmentLabel(p))}</div>${state.browseMode==='platform'?`<p class="scope-note platform-match">${escText(activePlatform()?.display_name||'Platform')} catalog result; application selector is ${escText(vehicle().year+' '+vehicle().make+' '+vehicle().model)}.</p>`:''}<div class="evidence-facts"><div><span>Product rating</span><strong>${p.rating.overall==null?'Awaiting review data':`${ratingText(p.rating.overall)} / 10`}</strong></div><div><span>Research links</span><strong>${new Set(sources.map(s=>s.url)).size}</strong></div><div><span>Recent USD offers</span><strong>${sortedOffers(p).length}</strong></div></div><div class="part-price-row"><div class="price-block"><small>${o.price==null?'No recent price':escText(o.seller)}</small><strong>${money(o.price)}</strong><div class="offer-count">${o.retrieved_at?`Checked ${new Date(o.retrieved_at).toLocaleDateString()}`:'Check product source'}</div></div><div class="card-actions"><button class="icon-button ${state.watches.includes(p.id)?'selected':''}" aria-label="Bookmark ${escText(p.name)}" onclick="toggleWatch('${escText(p.id)}')">${state.watches.includes(p.id)?'★':'☆'}</button><button class="button secondary small ${comp?'selected':''}" onclick="toggleCompare('${escText(p.id)}')">${comp?'Comparing':'Compare'}</button><button class="button secondary small" onclick="showPart('${escText(p.id)}')">Details</button><button class="button primary small" aria-pressed="${added}" onclick="toggleBuild('${escText(p.id)}')">${added?'✓ Added':'Add to build'}</button></div></div></article>`}
function renderCatalog(){const cats=categories();$('#categoryFilter').innerHTML=cats.map(c=>`<option ${c===state.category?'selected':''}>${escText(c)}</option>`).join('');$('#categoryButtons').innerHTML=cats.map(c=>`<button class="category-button ${c===state.category?'active':''}" data-category="${escText(c)}"><span>${escText(c)}</span><span>${c==='All'?compatibleParts().length:compatibleParts().filter(p=>p.category===c).length}</span></button>`).join('');$('#categoryButtons').querySelectorAll('[data-category]').forEach(btn=>btn.addEventListener('click',()=>setCategory(btn.dataset.category)));$('#difficultyFilter').value=state.difficulty;$('#maxPriceFilter').value=state.maxPrice;$('#hideUnverified').checked=state.hideUnverified;$('#sortSelect').value=state.sort;const list=filtered();$('#resultCount').textContent=`${list.length} results`;$('#catalogTitle').textContent=state.browseMode==='platform'?`${activePlatform()?.display_name||'Platform'} parts`:state.category==='All'?'Parts for your project':state.category;$('#partGrid').innerHTML=list.length?list.map(card).join(''):`<div class="empty-state"><strong>No catalog matches yet.</strong><p>Try another filter or vehicle. A vehicle record does not mean parts have verified fitment.</p><button class="button secondary" onclick="resetFilters()">Reset filters</button></div>`}
function parseShare(){const token=new URLSearchParams(location.search).get('build');if(!token)return;try{if(token.length>100000)throw new Error('Too large');persistGarage();acceptBuild(JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(token),c=>c.charCodeAt(0)))));state.browseMode='vehicle';toast('Shared build loaded')}catch(e){toast('Unable to load this build link. Your saved build is unchanged.')}}
function searchApplications(value){
 const root=$('#applicationResults'),tokens=value.trim().toLowerCase().split(/\s+/).filter(Boolean);
 root.hidden=!tokens.length;if(!tokens.length){root.replaceChildren();return}
 const matches=text=>tokens.every(t=>text.toLowerCase().includes(t));
 const platforms=DATA.platforms.filter(p=>matches([p.make,p.name,...(p.aliases||[])].join(' '))).map(p=>({id:p.id,label:p.display_name,kind:'platform'}));
 const cars=allVehicleRecords().filter(v=>matches([v.year,v.make,v.model,v.trim,v.engine,v.transmission].join(' '))).sort((a,b)=>vehiclePartCount(b.id)-vehiclePartCount(a.id)||b.year-a.year).map(v=>({id:v.id,label:[v.year,v.make,v.model,v.trim].join(' '),kind:'vehicle'}));
 const all=[...platforms,...cars];root.replaceChildren();
 const status=document.createElement('p');status.textContent=all.length?`${all.length} matches${all.length>20?' · showing first 20; add a year or engine to narrow':''}`:'No matching car or engine in this catalog.';root.append(status);
 for(const row of all.slice(0,20)){const button=document.createElement('button');button.type='button';button.className='button secondary small';button.textContent=row.label;button.addEventListener('click',()=>{state.browseMode=row.kind==='platform'?'platform':'vehicle';if(row.kind==='platform')switchPlatform(row.id);else switchVehicle(row.id);root.hidden=true;$('#applicationSearch').value='';});root.append(button)}
}
$('#applicationSearch').addEventListener('input',e=>searchApplications(e.target.value));
$('#applicationSearch').addEventListener('keydown',e=>{if(e.key==='Escape')$('#applicationResults').hidden=true});
window.setBrowseMode=setBrowseMode;window.selectCarLevel=selectCarLevel;window.selectPlatformLevel=selectPlatformLevel;window.switchPlatform=switchPlatform;
boot();
